/* ---------- 0.17.0: family talismans (one per family, offered only when the team has that family) + «Узы стаи» ---------- */
for(const[k,f]of Object.entries(FAM))TAL['fm_'+k]={n:'Знак: '+f.n,ic:f.ic,r:0,fam:k,t:`Твои ${f.n.toLowerCase()} бьют на 3 сильнее и в начале боя получают щит 9.`};
TAL.bond={n:'Узы стаи',ic:'🔗',r:1,t:'Если в стае 3 или больше существ одного семейства, в начале боя все твои получают щит 15.'};
const runFams=R=>R.team.map(m=>PETS[m.pi].fam);

/* ---------- 0.18.0: «Кодекс». Everything met in the game: bosses, elites, talismans, run events. Unseen entries stay hidden ---------- */
const cdx=()=>{META.codex=META.codex||{boss:{},el:{},tal:{},ev:{}};return META.codex};
const cdxMark=(sec,k)=>{const c=cdx();if(!c[sec][k]){c[sec][k]=1;saveMeta()}};
const CDX_TABS=[['boss','👑','Боссы'],['el','💀','Элиты'],['tal','🧿','Талисманы'],['ev','❓','События']];
function cdxList(sec){
  if(sec==='boss')return Object.entries(BOSSES).map(([k,b])=>({k,ic:petIc({n:b.n,ic:b.ic},1),n:b.n,t:b.rule,x:`Здоровье ${b.hp*K/2}, ${b.mp} карты за ход. Земля: ${ACTS.find(a=>a.bosses.includes(k))?.n||'—'}.`}));
  if(sec==='el')return Object.entries(ELM).map(([k,e])=>({k,ic:e.ic,n:e.n,t:'Враги '+e.t+'.'}));
  if(sec==='tal')return Object.entries(TAL).map(([k,t])=>({k,ic:t.ic,n:t.n,t:t.t,x:['Обычный','Редкий','Легендарный'][t.r||0]}));
  return EVENTS.map(e=>({k:e.k,ic:e.ic,n:e.n,t:e.t,x:(e.act!=null?'Только в земле: '+ACTS[e.act].n+'. ':'')+'Выборы: '+e.ch.map(c=>c.t).join(' / ')}))}
const cdxCount=()=>{const c=cdx();return CDX_TABS.reduce((a,[s])=>a+cdxList(s).filter(x=>c[s][x.k]).length,0)};
const cdxTotal=()=>CDX_TABS.reduce((a,[s])=>a+cdxList(s).length,0);
function renderCodex(){const c=cdx(),sec=ui.cdx||'boss',l=cdxList(sec),seen=l.filter(x=>c[sec][x.k]).length;
  setApp(`<div class="top"><button class="pill sm" data-act="m-menu">‹ Меню</button><div class="title">Кодекс</div><span class="m">${cdxCount()}/${cdxTotal()}</span></div>
  <div class="modes" style="margin-bottom:6px">${CDX_TABS.map(([s,ic,n])=>`<button class="pill sm ${s===sec?'on':''}" data-act="cx-${s}">${ic} ${n} <span class="m">${cdxList(s).filter(x=>c[s][x.k]).length}/${cdxList(s).length}</span></button>`).join('')}</div>
  <div class="m" style="font-size:12px;margin-bottom:6px">${sec==='boss'?'Боссы открываются, когда ты встречаешь их в бою.':sec==='el'?'Элиты встречаются в Забеге на клетках 💀.':sec==='tal'?'Талисман попадает в Кодекс, когда ты берёшь его в Забеге.':'События открываются на клетках ❓ Забега.'} Открыто ${seen} из ${l.length}.</div>
  <div class="qlist">${l.filter(x=>c[sec][x.k]).map(x=>`<div class="cdx"><span class="cdx-ic">${x.ic}</span><span style="flex:1"><b>${x.n}</b><div class="m" style="font-size:11px">${x.t}</div>${x.x?`<div class="m" style="font-size:10px;opacity:.8">${x.x}</div>`:''}</span></div>`).join('')}</div>
  ${seen<l.length?`<div class="m" style="font-size:12px;margin:10px 0 4px">Ещё не открыто: ${l.length-seen}</div><div class="cdx-un">${'<span>❔</span>'.repeat(l.length-seen)}</div>`:''}`)}
function codexClick(act){
  if(act==='m-codex'){CTX=null;NEXT=null;G={phase:'codex'};resetPlace();render();return true}
  if(act.startsWith('cx-')){ui.cdx=act.slice(3);render();return true}
  return false}
ACH.push({k:'codex40',ic:'📖',n:'Летописец',t:'Открой 40 записей Кодекса',g:()=>[cdxCount(),40],st:40},{k:'codexall',ic:'📜',n:'Всё записано',t:'Открой весь Кодекс',g:()=>[cdxCount(),cdxTotal()],st:150});

/* ---------- 0.19.1: boss intro card when a boss battle starts ---------- */
function bossIntroHtml(k){const B=BOSSES[k];const lair=CTX&&CTX.kind==='lair'?LAIR_T[CTX.tier]:null;
  return`<div class="over bintro" data-act="bi-x"><div class="box"><div class="bi-art">${petIc({n:B.n,ic:B.ic},1)}</div><h2>${B.n}</h2>
  <div class="m" style="font-size:12px">${lair?lair.ic+' '+lair.n+' · ':''}здоровье ${G.B.pets[0].max} · ${B.mp} карты за ход</div><div style="font-size:13px;margin:8px 0">${B.rule}</div>
  <div class="acts"><button class="btn" data-act="boss-deck">Колода босса</button><button class="btn main" data-act="bi-x">В бой</button></div></div></div>`}
function introClick(a){if(a==='bi-x'){ui.bIntro=null;render();return true}if(a==='boss-deck'&&ui.bIntro){ui.bIntro=null}return false}
/* first launch: a welcome window once */
function welcomeClick(a){if(a==='wl-no'){META.welcome=1;saveMeta();render();return true}return false}

