const PUZMAX={"Бес": 27, "Богомол": 32, "Виверна": 26, "Вихрик": 27, "Водяной": 29, "Волк": 25, "Глазун": 29, "Голем": 35, "Грифон": 30, "Демон хаоса": 32, "Джинн": 27, "Дракончик": 28, "Дрон": 25, "Дубовик": 33, "Единорог": 35, "Жук-носорог": 42, "Златокрыл": 26, "Искрун": 21, "Кальмар": 32, "Каменный дракон": 36, "Козлорог": 31, "Колючник": 29, "Комар": 22, "Лиса": 27, "Лотосовик": 21, "Медведь": 38, "Медуза": 23, "Мехзмей": 25, "Мехскорпион": 23, "Мухолов": 26, "Огневик": 24, "Олень": 28, "Осьминог": 29, "Паук": 37, "Пчела": 28, "Робот": 32, "Русалка": 17, "Светлячок": 16, "Слизень": 37, "Сова": 28, "Солнечник": 21, "Тенекот": 28, "Тёмный дракон": 33, "Фея": 28, "Цербер": 29};
function puzBuild(z){CTX={kind:'puz',i:PUZ.indexOf(z),z};TEAM=z.P.map(x=>PETS.findIndex(p=>p.n===x.n));PLACE=z.P.map(x=>[x.r,x.c]);
  NEXT={enemyIdx:z.B.map(x=>PETS.findIndex(p=>p.n===x.n)),ai:'easy'};G={phase:'battle'};resetPlace();newGame();
  const P=G.P,B=G.B;for(const p of P.pets)if(PUZMAX[p.n]){p.max=PUZMAX[p.n]*SC;p.hp=p.max}
  B.pets.forEach((p,i)=>{p.r=z.B[i].r;p.c=z.B[i].c;if(PUZMAX[p.n])p.max=PUZMAX[p.n]*SC;p.hp=z.B[i].hp3||z.B[i].hp*SC});
  P.hand=z.hand.map((h,i)=>({uid:'Z'+i,t:h.t,pet:h.p!=null?P.pets[h.p].id:null}));P.deck=[];P.discard=[];P.plan=[];P.pool={...z0(),...z.pool};
  B.hand=[];B.deck=[];B.discard=[];B.plan=[];B.pool=z0();ui.pzHint=false;render()}
function puzHintTxt(z){return z.sol.map(e=>{const h=z.hand[+e.cu.slice(1)],t=T[h.t],who=h.p!=null?z.P[h.p].n:'';
  if(e.dir)return`👣 ${t.n}: ${(z.P.find((x,i)=>'p'+i===e.petT)||{}).n||'существо'} ${e.dir[0]<0?'вверх':e.dir[0]>0?'вниз':e.dir[1]<0?'влево':'вправо'}`;
  return`▲ ${t.n} (${who})${e.cell?` в клетку: ${['ближний к фронту','средний','дальний'][e.cell[0]]} ряд, ${e.cell[1]+1}-я слева`:e.petT?' на союзника':''}`}).join('<br>')+'<br><span class="m">Остальные карты не трогай.</span>'}
function renderPuzList(){const s=pzs(),n=Object.keys(s.done).length;
  setApp(`<div class="top"><button class="pill sm" data-act="m-menu">‹ Меню</button><div class="title">Задачи</div><span class="m">${n}/${PUZ.length} ✓</span></div>
  <div class="m" style="font-size:12px;margin:-2px 0 8px">Победи за один ход. Существа, карты и стихии заданы, враги не ходят. Важны инициатива карт ⏱, клетки и порядок ударов. Решение есть всегда.</div>
  ${PZD.map((d,di)=>`<div class="msec">${d[1]} ${d[0]}</div><div class="pz-grid">${PUZ.map((z,i)=>z.d===di?`<button class="pz ${s.done[i]?'ok':''}" data-act="pz-${i}"><b>${i+1}</b><span>${s.done[i]?'✓':z.B.map(x=>petIc(PETS.find(p=>p.n===x.n),1)).join('')}</span></button>`:'').join('')}</div>`).join('')}`)}
function puzOver(){const c=CTX,s=pzs();if(G.over==='win'&&!s.done[c.i]){questEv('puz');s.done[c.i]=1;G.rw=[];giveSt(PZD[c.z.d][2],G.rw);c.first=true;saveMeta()}}
function puzOverHtml(){const c=CTX;
  const body=G.over==='win'?`<div class="m">Задача ${c.i+1} решена!${c.first?'':' (уже была решена)'}</div>`:`<div class="m">Не вышло: враги остались на поле. Попробуй другой порядок или другие клетки.</div>${ui.pzHint?`<div class="pz-hint">${puzHintTxt(c.z)}</div>`:''}`;
  const nx=PUZ.findIndex((z,i)=>i>c.i&&!pzs().done[i]);
  return{body,btn:G.over==='win'?`<button class="btn" data-act="m-puz">К задачам</button>${nx>=0?`<button class="btn main" data-act="pz-${nx}">Следующая</button>`:''}`
    :`<button class="btn" data-act="pz-hint">💡 Решение</button><button class="btn main" data-act="pz-${c.i}">Ещё раз</button>`}}
function puzClick(act){
  if(act==='m-puz'){CTX=null;NEXT=null;G={phase:'puzlist'};resetPlace();render();return true}
  if(act==='pz-hint'){ui.pzHint=true;render();return true}
  if(act==='pz-reset'&&CTX&&CTX.kind==='puz'){puzBuild(CTX.z);return true}
  if(/^pz-\d+$/.test(act)){const z=PUZ[+act.slice(3)];if(z)puzBuild(z);return true}
  return false}
ACH.push({k:'puz10',ic:'🧩',n:'Головоломка',t:'Реши 10 задач',g:()=>[Object.keys(pzs().done).length,10],st:40},{k:'puzall',ic:'🧠',n:'Гроссмейстер',t:'Реши все задачи',g:()=>[Object.keys(pzs().done).length,PUZ.length],st:120});

/* ---------- 0.20.0: weekly quests. Three bigger goals per week; rewards are stones plus fragments of a creature you do not have yet ---------- */
const WDEF={
  win20:{t:'Выиграй 20 боёв',g:20,ev:'win',st:40},
  kill60:{t:'Победи 60 вражеских существ',g:60,ev:'kill',st:40},
  node15:{t:'Пройди 15 точек Забега',g:15,ev:'node',st:50},
  lair3:{t:'Победи 3 босса в Логовах',g:3,ev:'lair',st:50},
  rank5:{t:'Выиграй 5 боёв в Лиге',g:5,ev:'rank',st:50},
  puz3:{t:'Реши 3 задачи',g:3,ev:'puz',st:40},
  dmg2k:{t:'Нанеси 2000 урона',g:2000,ev:'dmg',st:40},
  flaw3:{t:'Победи 3 раза, не потеряв ни одного существа',g:3,ev:'flawless',st:50},
};
const weekKey=()=>Math.floor((Date.now()/864e5+3)/7);
function questsWeek(){const w=weekKey();if(!META.wq||META.wq.w!==w){META.wq={w,list:shuffle(Object.keys(WDEF)).slice(0,3).map(k=>({k,p:0,cl:false}))};saveMeta()}return META.wq.list}
function weekClaim(i){const q=questsWeek()[i],D=WDEF[q.k];if(!q||q.cl||q.p<D.g)return null;q.cl=true;const log=[];giveSt(D.st,log);
  const lk=shuffle(PETS.filter(p=>!mp(p.n).un));if(lk.length)giveFr(lk[0].n,10,log);else giveSt(20,log);saveMeta();return log}
const weekLeft=()=>{const ms=(weekKey()+1)*7*864e5-3*864e5-Date.now(),d=Math.floor(ms/864e5),h=Math.floor(ms%864e5/36e5);return d?`${d} д. ${h} ч.`:`${h} ч.`};
function weekHtml(){return questsWeek().map((q,i)=>{const D=WDEF[q.k],done=q.p>=D.g;return`<div class="qst ${q.cl?'cl':''}"><span style="flex:1"><b>${D.t}</b><div class="xpb sm"><i style="width:${100*q.p/D.g}%"></i><span>${q.p}/${D.g}</span></div></span><span class="m" style="font-size:11px">💎${D.st} 🧩10</span>${q.cl?'<span class="m">✓</span>':`<button class="pill sm ${done?'on':''}" data-act="wc-${i}" ${done?'':'disabled'}>Забрать</button>`}</div>`}).join('')}
function weekClick(a){if(a.startsWith('wc-')){const l=weekClaim(+a.slice(3));if(l)toast(l.map(x=>x.k==='st'?'💎 +'+x.v:x.k==='fr'?'🧩 +'+x.v+' '+x.n:'').join(' · '));render();return true}return false}
/* 0.21.3: stone → fragment exchange in the creature sheet. Sims showed stones pile up (4000+ unspent after 60 runs) while fragments gate progress.
   Once per creature per day: 40 💎 → 5 🧩 of that creature (locked creatures too) */
const FRX={st:40,fr:5};
const frxDone=n=>{const d=dayKey();if(!META.frx||META.frx.d!==d)META.frx={d,n:{}};return !!META.frx.n[n]};
function frxBuy(n){if(frxDone(n)||META.stones<FRX.st)return null;META.stones-=FRX.st;META.frx.n[n]=1;const log=[];giveFr(n,FRX.fr,log);saveMeta();return log}
function frxHtml(p,i){const m=mp(p.n);if(m.un&&m.q>=4)return'';const done=frxDone(p.n);
  return`<div class="qup"><div><b>Обмен камней</b><div class="m" style="font-size:11px">${done?'Сегодня уже обменял. Завтра снова.':`${FRX.st} 💎 → ${FRX.fr} 🧩 этого существа, раз в день.`}</div></div><button class="btn" data-act="frx-${i}" ${!done&&META.stones>=FRX.st?'':'disabled'}>💎${FRX.st} → 🧩${FRX.fr}</button></div>`}
function frxClick(a){if(a.startsWith('frx-')){const p=PETS[+a.slice(4)],l=p&&frxBuy(p.n);if(l)toast(l.map(x=>x.k==='fr'?'🧩 +'+x.v+' '+x.n:x.k==='new'?'✨ '+x.n+' открыт!':'').join(' · '));render();return true}return false}

/* ---------- 0.21.1: profile stats on top of the achievements page ---------- */
function statsHtml(){const s=META.stats||{},fav=Object.entries(META.pst||{}).sort((a,b)=>b[1].b-a[1].b)[0],lg=LEAGUES[rk().top||0];
  const stars=Object.keys(BOSSES).reduce((a,k)=>a+lairOf(k).t,0),own=PETS.filter(p=>mp(p.n).un).length;
  const it=(ic,v,t)=>`<div class="st-i"><span>${ic}</span><b>${v}</b><small>${t}</small></div>`;
  return`<div class="st-g">${it('⚔️',`${s.wins||0}/${s.battles||0}`,'побед / боёв')}${it('💀',s.kills||0,'врагов побеждено')}${it('🧭',`${s.runWins||0}/${s.runs||0}`,'забегов пройдено')}
  ${it('👑',`${stars}/${Object.keys(BOSSES).length*3}`,'звёзд в Логовах')}${it(lg.ic,lg.n,'лучшая лига')}${it('🧩',`${Object.keys(pzs().done).length}/${PUZ.length}`,'задач решено')}
  ${it('📚',`${own}/${PETS.length}`,'существ открыто')}${it('📖',`${cdxCount()}/${cdxTotal()}`,'записей Кодекса')}${fav?it(petIc(PETS.find(p=>p.n===fav[0])||{ic:'🐾'},1),fav[0],`любимец: ${plN(fav[1].b,'бой','боя','боёв',1)}`):''}${(()=>{const d=Object.entries(META.pst||{}).filter(e=>e[1].d).sort((a,b)=>b[1].d-a[1].d)[0];return d?it(petIc(PETS.find(p=>p.n===d[0])||{ic:'🐾'},1),d[0],`больше всех урона: ${d[1].d}`):''})()}</div>`}
/* 0.21.3: a new screen always opens at the top (opening Достижения from the bottom of the menu used to land mid-page) */
/* 0.22.0: «Итоги боя» on the result screen: damage dealt / taken and kills per creature. BST_A = the creature whose card is being executed */
let BST_A=null;
function bstHit(S,p,v){if(SIMU||!G||!v)return;const b=G.bst=G.bst||{},key=(s,id)=>(s===G.P?'P':'B')+id,o=k=>b[k]=b[k]||{d:0,t:0,k:0};
  o(key(S,p.id)).t+=v;if(BST_A&&BST_A.S!==S){const a=o(key(BST_A.S,BST_A.id));a.d+=v;if(p.hp-v<=0)a.k++}}
function bstClick(a){if(a==='bst'){ui.bst=!ui.bst;render();return true}return false}
/* 0.22.1: choose the card in each slot right on the pick screen (pet sheet), not only in the library. WoW-pet-battle style prep before a boss */
function petSlotsHtml(pi,one){const p=PETS[pi],m=mp(p.n);
  return p.cards.map((k,j)=>{const alt=p.alt&&p.alt[j],open=alt&&altOpen(m.q,j),cur=open&&m.sl[j]?alt:k;
    const sw=open?`<div class="pslot"><button class="pill sm ${m.sl[j]?'':'on'}" data-act="psl-${pi}-${j}-0">${T[k].n}</button><button class="pill sm ${m.sl[j]?'on':''}" data-act="psl-${pi}-${j}-1">${T[alt].n}</button></div>`
      :alt?`<div class="m" style="font-size:11px;margin-top:-2px">Вторая карта «${T[alt].n}» откроется на качестве «${QN[j+1]}».</div>`:'';
    return sw+one(cur,T[cur])}).join('')}
function slotClick(a){const r=/^psl-(\d+)-(\d)-([01])$/.exec(a);if(r){const m=mp(PETS[+r[1]].n);m.sl[+r[2]]=+r[3];saveMeta();render();return true}return false}
/* 0.23.0: «Подвиги» in the lairs: one extra goal per boss (win in N turns or without losses), counted on ⭐⭐ or ⭐⭐⭐. Once: 50 💎 + 10 🧩 */
const FEAT={forest:{t:13},queen:{fl:1},spider:{t:12},hydra:{fl:1},witch:{t:16},boneking:{fl:1},golem:{t:10},ash:{fl:1},storm:{t:12},trick:{fl:1},leech:{t:8},clock:{t:14}};
const featTxt=k=>{const f=FEAT[k];return f?f.t?`победи за ${f.t} ходов или быстрее`:'победи, не потеряв ни одного существа':''};
