/* 0.25.0: «Охота недели» in the lairs: three bosses in a row (one per land, same for everyone this week) on the Обычный tier,
   one team, wounds stay (+50% healing between fights, the fallen come back at 25%). Full clear once a week: 60 💎 + 10 🧩 */
const rushList=()=>{const w=weekKey();return ACTS.map((a,i)=>a.bosses[(w*7+i*3)%a.bosses.length])};
const rushS=()=>{META.rush=META.rush||{};if(META.rush.w!==weekKey())META.rush={w:weekKey(),best:0,done:false};return META.rush};
function rushStart(){CTX={kind:'lair',bk:rushList()[0],tier:0,rush:{list:rushList(),i:0,hp:null}};NEXT=null;G={phase:'pick'};resetPlace();TEAM=TEAM.filter(i=>mp(PETS[i].n).un||sandbox());ui.pv=null;ui.psheet=false;render()}
function rushNext(){const r=CTX.rush;CTX.bk=r.list[r.i];CTX.rec=false;CTX.first=false;CTX.feat=false;CTX.featMiss=false;G={phase:'battle'};newGame();
  G.P.pets.forEach((p,j)=>{const h=r.hp[j];p.hp=h<=0?Math.round(p.max*.25):Math.min(p.max,h+Math.round(p.max*.5))});render()}
function rushHtml(){const s=rushS(),l=rushList();
  return`<div class="lair rush"><div class="lair-h"><span class="lair-ic">⚔️</span><span style="flex:1"><b>Охота недели</b><div class="m" style="font-size:11px">Три босса подряд одной стаей, сложность Обычный. Раны остаются: между боями выжившие лечатся на 50%, павшие встают с четвертью здоровья. Ещё ${weekLeft()}</div></span></div>
  <div class="rush-l">${l.map((k,i)=>`<span class="${i<s.best?'ok':''}">${petIc({n:BOSSES[k].n,ic:BOSSES[k].ic},1)}<b>${BOSSES[k].n}</b></span>`).join('<i>›</i>')}</div>
  <div class="feat ${s.done?'ok':''}">${s.done?'Пройдена на этой неделе ✓':`Награда за всех троих: 💎60 и 🧩10. Лучшее: ${s.best} из 3.`}</div>
  <button class="btn main" data-act="rush-go" style="margin-top:8px">${s.done?'Пройти ещё раз':'Начать охоту'}</button></div>`}
function rushClick(a){if(a==='rush-go'){rushStart();return true}if(a==='rush-next'&&CTX&&CTX.rush){rushNext();return true}return false}
